    QSellerShipment sellerShipment = QSellerShipment.sellerShipment;

    // 필터 조건 생성
    BooleanExpression emailCondition = saleBid.seller.email.eq(email);
    BooleanExpression statusCondition = saleBidStatus != null ? saleBid.status.stringValue().eq(saleBidStatus) : null;
    BooleanExpression saleStatusCondition = saleStatus != null ? sale.status.stringValue().eq(saleStatus) : null;

    // 쿼리 실행
    try {
        // Main Query
        List<SaleBidResponseDto> content = queryFactory
                .select(Projections.constructor(
                        SaleBidResponseDto.class,
                        saleBid.id,
                        product.id,
                        product.name,
                        product.englishName,
                        productSize.size,
                        productColor.colorName,
                        productImage.imageUrl,
                        saleBid.bidPrice,
                        saleBid.status.stringValue(),
                        sale.status.stringValue(),
                        sellerShipment.status.stringValue(),
                        saleBid.createdDate,
                        saleBid.modifiedDate,
                        saleBid.isInstantSale
                ))
                .from(saleBid)
                .join(saleBid.seller).on(emailCondition)
                .join(saleBid.productSize, productSize)
                .join(productSize.productColor, productColor)
                .join(productColor.product, product)
                .join(productColor.thumbnailImage, productImage)
                .leftJoin(saleBid.sale, sale)
                .leftJoin(sale.sellerShipment, sellerShipment)
                .where(
                        statusCondition,
                        saleStatusCondition
                )
                .orderBy(saleBid.createdDate.desc()) // 최신순 정렬
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();

        // Count Query for pagination
        Long countResult = queryFactory
                .select(saleBid.count())
                .from(saleBid)
                .join(saleBid.seller).on(emailCondition)
                .leftJoin(saleBid.sale, sale)
                .where(
                        statusCondition,
                        saleStatusCondition
                )
                .fetchOne();

        // fetchOne()이 null을 반환할 수 있으므로 안전하게 처리
        long total = countResult != null ? countResult : 0L;

        log.debug("판매 입찰 조회 결과 - 총 {}건, 현재 페이지 {}건", total, content.size());
        return new PageImpl<>(content, pageable, total);
    } catch (Exception e) {
        log.error("판매 입찰 목록 조회 중 오류 발생", e);
        throw e;
    }
}

/**
 * 사용자별 판매 입찰 상태 카운트 조회
 */
        Long userId,
        SortOption sortOption,
        Pageable pageable) {
    log.debug("사용자 관심 상품 목록 조회 시작 - 사용자ID: {}, 페이지: {}, 사이즈: {}",
            userId, pageable.getPageNumber(), pageable.getPageSize());

    // QueryDSL Q-클래스 초기화
    QInterest interest = QInterest.interest;
    QInterest interest1 = new QInterest("interest1");
    QProduct product = QProduct.product;
    QProductColor productColor = QProductColor.productColor;
    QProductSize productSize = QProductSize.productSize;
    QProductImage productImage = QProductImage.productImage;

    try {
        // 데이터 조회 쿼리 (페이징 처리)
        log.debug("관심 상품 데이터 조회 쿼리 실행 - 사용자ID: {}", userId);
        List<Tuple> results = queryFactory.select(
                        interest.id,
                        product.id,
                        product.name,
                        product.englishName,
                        product.releasePrice, // releasePrice 추가
                        productColor.id,
                        productColor.thumbnailImage.imageUrl,
                        productColor.colorName,
                        productSize.purchasePrice.min(),
                        JPAExpressions
                                .select(interest1.count())
                                .from(interest1)
                                .where(interest1.productColor.eq(productColor))
                )
                .from(interest)
                .leftJoin(interest.productColor, productColor) // 일반 Join
                .leftJoin(productColor.product, product) // 일반 Join
                .leftJoin(productColor.thumbnailImage, productImage) // Thumbnail 이미지 조인 추가
                .leftJoin(productColor.sizes, productSize) // 일반 Join
                .leftJoin(productColor.interests, interest1)
                .where(interest.user.id.eq(userId))
                .groupBy(
                        product.id,
                        productColor.id,
                        productColor.thumbnailImage.imageUrl)
                .orderBy(getOrderByClause(sortOption, product, productColor, productSize)) // 정렬 추가
                .offset(pageable.getOffset())
