                        product.englishName,
                        product.releasePrice,
                        productColor.id,
                        productColor.colorName,
                        productColor.thumbnailImage.imageUrl,
                        productSize.purchasePrice.min(), // 최저 구매가
                        interest.count(),                 // 관심 수
